-- Regelsatz ministerium: Änderungsauftrag 3 als Zählregel der Art personentage (Vorschlag uc3/26), freigegeben.
-- Erzeugt am 05.11.2026 aus der Abgabe-Datenbank (meta.regel), damit eine frische Datenbank (`uc3 db init`)
-- denselben Regelstand hat wie die Abgabe (Jury-Probe 4d, B1). Werte, Texte und die festgehaltene Freigabe
-- (Name, Zeitpunkt) stehen wie in der Abgabe; der Freigabe-Commit ist 08e63c0; die Lieferung 2026-07 selbst ist Commit 1b0f799.
-- Idempotent: ON CONFLICT DO NOTHING. Eine Datenbank, in der der Regelsatz schon steht, bleibt unverändert.

INSERT INTO meta.regel (regelsatz, name, typ, art, reihenfolge, parameter, beschreibung, begruendung, grundlage, gueltig_ab_lieferung, gueltig_bis_lieferung, aktiv, freigegeben_von, freigegeben_am, ersetzt_regel_id) VALUES

('ministerium', 'M01_personentage_ministerium', 'zaehl', 'personentage', 10, '{"datei": "ministerium_{berichtsmonat}.csv", "felder": ["PERSON_ID", "GESCHLECHT", "GEBURTSJAHR", "TAGE"], "monate": 12, "oenace": "C", "datenstand": "juengste_lieferung_je_tag", "mindesttage": 200, "trennzeichen": ";", "qualifikationen": ["ArbeiterDV", "ArbeiterFD"], "bereinigung_regelsatz": "v1", "altcodes_als_abschnitt": ["DA", "DB", "DC", "DD", "DE", "DF", "DG", "DH", "DI", "DJ", "DK", "DL", "DM", "DN"], "angehaltene_lieferungen": "ueberspringen", "geburtsjahr_unplausibel": "Unbekannt"}'::jsonb, 'Personenliste für das Ministerium: gezählt werden Personen mit mindestens 200 Kalendertagen im Zeitraum der letzten zwölf Monate bis einschließlich Berichtsmonat, wenn an den Tagen mindestens ein passender Abschnitt als ArbeiterDV oder ArbeiterFD im ÖNACE-Abschnitt C besteht. Je Kalendertag gilt die jüngste Lieferung, die diesen Tag enthält, nach Regelsatz v1; angehaltene Teil-Lieferungen werden übersprungen. Die Ausgabe erfolgt als CSV mit Semikolon, sortiert nach PERSON_ID.', 'Die Anforderung beschreibt ausdrücklich eine neue Zählregel der Art personentage im Regelsatz ministerium. Die Parameter decken Berichtsmonat/12-Monats-Fenster, Qualifikationen, ÖNACE-Abschnitt C inkl. Altcodes DA bis DN, Mindesttage, Datenstand je Tag, Überspringen angehaltener Lieferungen, Bereinigungsstand v1 sowie Ausgabeformat und Felder ab.', 'Auftrag 3 und Kontext zur neuen Regelart personentage; Vorschlag uc3/26: Auftrag 3, Datenlieferung an das Ministerium: Das Ministerium erhält eine Liste aller Personen, die in den letzten zwölf Monaten bis einschließlich Berichtsmonat mindestens 200 Tage als Arbeiter beschäftigt waren, mit Dienstvertrag oder freiem Dienstvertrag (ArbeiterDV, ArbeiterFD), im ÖNACE-Abschnitt C. Der Berichtsmonat ist ein Parameter, für die Abgabe 07/2026, also der Zeitraum 01.08.2025 bis 31.07.2026. Tage sind Kalendertage, an denen mindestens ein passender Zeitabschnitt besteht; gleichzeitige Verhältnisse zählen einen Tag nur einmal, DV- und FD-Tage werden zusammengezählt. Datenstand: Für jeden Tag gilt die jüngste Lieferung, die diesen Tag enthält, verarbeitet nach unseren Regeln (Regelsatz v1); eine Lieferung, deren Monatslauf angehalten wurde (Teil-Lieferung), wird dabei übersprungen. Wirtschaftszweig ist die ÖNACE des jeweiligen Zeitabschnitts, wie ihn die verwendete Lieferung ausweist: bis 12/2024 nach ÖNACE 2008, ab 01/2025 nach ÖNACE 2025, gezählt wird Abschnitt C; die alten ÖNACE-2003-Codes DA bis DN zählen wie in unserer Zuordnungsregel Q01 zu C. Felder: PERSON_ID, GESCHLECHT, GEBURTSJAHR (bei unplausiblem Geburtsdatum Unbekannt), TAGE. Format: CSV mit Semikolon, Datei ministerium_JJJJ-MM.csv, sortiert nach PERSON_ID. Setze das als Regel um, nicht als Code: eine neue Regel (regel_neu) vom Typ zaehl der Art personentage im Regelsatz ministerium, mit den Parametern, die diese Art kennt.', '2024-08', NULL, true, 'Bernhard Götzendorfer', TIMESTAMPTZ '2026-11-05T15:54:13.330572+00:00', NULL::int)
ON CONFLICT (regelsatz, name) DO NOTHING;
